import { useState } from 'react';

function AddMovieForm({ onAdd }) {
  const [title, setTitle] = useState('');
  const [year, setYear] = useState('');
  const trimmed = title.trim();

  function handleSubmit(e) {
    e.preventDefault();
    if (!trimmed) return;
    onAdd(trimmed, year === '' ? null : Number(year));
    setTitle('');
    setYear('');
  }

  return (
    <form onSubmit={handleSubmit}>
      <label htmlFor="title">Title</label>
      <input id="title" value={title} onChange={(e) => setTitle(e.target.value)} />
      <label htmlFor="year">Year</label>
      <input id="year" type="number" value={year} onChange={(e) => setYear(e.target.value)} />
      <button type="submit" disabled={!trimmed}>Add</button>
    </form>
  );
}

let nextId = 1; // in a real app: crypto.randomUUID()

export default function App() {
  const [movies, setMovies] = useState([]);

  function addMovie(title, year) {
    setMovies([...movies, { id: nextId++, title, year }]);
  }

  return (
    <main>
      <AddMovieForm onAdd={addMovie} />
      <ul>
        {movies.map((m) => (
          <li key={m.id}>{m.year ? `${m.title} (${m.year})` : m.title}</li>
        ))}
      </ul>
    </main>
  );
}
